  const wrong=bin&&Object.values(s.items).find(b=>b.location==="bin"&&b.bin===bin.id&&sorting&&b.type!==bin.id);
  if(wrong)return {type:"pickup",item:wrong.id,label:"取回放错的"+TYPES[wrong.type].name};
