 s.player={x:8.25,z:-2,yaw:0};s=e.updateEnvironment(s,s.weather.remaining);assert.equal(s.weather.raining,true);assert.ok(s.weather.remaining>=60&&s.weather.remaining<=90);assert.equal(s.weather.storm,1);
